INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21FK9YP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylinder has a radius of $6$ cm and a height of $11$ cm. What is the volume of the cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$36\\pi$ cm$^3$"},{"key":"B","text":"$66\\pi$ cm$^3$"},{"key":"C","text":"$132\\pi$ cm$^3$"},{"key":"D","text":"$396\\pi$ cm$^3$"}]$lyceon_json$::jsonb, 'D', NULL, E'The volume of a cylinder is $V = \\pi r^2 h = \\pi(6)^2(11) = \\pi(36)(11) = 396\\pi$ cm$^3$. The value $36\\pi$ results from computing only $\\pi r^2$ and omitting the height, giving just the base area. The value $66\\pi$ results from using $\\pi r h$ instead of $\\pi r^2 h$, forgetting to square the radius: $\\pi(6)(11) = 66\\pi$. The value $132\\pi$ results from computing the lateral surface area $2\\pi r h = 2\\pi(6)(11) = 132\\pi$ instead of the volume.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21P47E4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A health magazine reports that people who drink at least $3$ cups of green tea per day have, on average, lower blood pressure than those who drink no green tea. The data comes from a survey of $1{,}200$ adults who self-reported their tea consumption and had their blood pressure measured. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Drinking green tea causes lower blood pressure."},{"key":"B","text":"There is an association between green tea consumption and lower blood pressure, but a causal relationship cannot be established from this study."},{"key":"C","text":"The study proves that green tea has no effect on blood pressure."},{"key":"D","text":"The results can be generalized only to the $1{,}200$ adults surveyed."}]$lyceon_json$::jsonb, 'B', NULL, E'Because this is an observational study (participants were not randomly assigned to drink or not drink green tea), we can identify an association between green tea consumption and lower blood pressure, but we cannot establish causation. Confounding variables (such as overall diet or exercise habits) may explain the difference. The distractor claiming causation overstates what an observational study can demonstrate. The distractor claiming the study proves no effect directly contradicts the reported finding. The distractor limiting the results to only the surveyed individuals is too restrictive; if the $1{,}200$ adults were randomly selected from a larger population, the association can be generalized to that population, though causation still cannot be inferred.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22EVXLE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'The ages, in years, of $8$ members of a hiking club are $23, 27, 29, 34, 34, 37, 41, 62$. If the oldest member (age $62$) leaves the club, which of the following statements about the remaining $7$ members'' ages is true?', NULL, $lyceon_json$[{"key":"A","text":"The mean decreases and the median stays the same."},{"key":"B","text":"The mean decreases and the median decreases."},{"key":"C","text":"The mean stays the same and the median decreases."},{"key":"D","text":"The mean increases and the median stays the same."}]$lyceon_json$::jsonb, 'A', NULL, E'With all $8$ members, the mean is $\\frac{23+27+29+34+34+37+41+62}{8} = \\frac{287}{8} = 35.875$ and the median is $\\frac{34+34}{2} = 34$. After removing $62$, the mean becomes $\\frac{225}{7} \\approx 32.14$, which is lower. The new median of the $7$ remaining values ($23, 27, 29, 34, 34, 37, 41$) is the $4$th value, which is $34$. The median stays the same. The claim that both decrease is incorrect because the median remains at $34$. The claim that the mean stays the same ignores the effect of removing the large outlier. The claim that the mean increases reverses the direction of the change caused by removing a value above the mean.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22OVF50', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'grid_in', E'The function $f$ is defined by $f(x) = a \\cdot b^x$, where $a$ and $b$ are positive constants. If $f(1) = 18$ and $f(4) = 486$, what is the value of $f(0)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'From the given values: $ab = 18$ and $ab^4 = 486$. Dividing the second equation by the first: $\\frac{ab^4}{ab} = b^3 = \\frac{486}{18} = 27$, so $b = 3$. Substituting back into $ab = 18$: $a(3) = 18$, giving $a = 6$. Therefore $f(0) = 6 \\cdot 3^0 = 6 \\cdot 1 = 6$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM236ERFP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'Right triangle $PQR$ has a right angle at $Q$, and $\\cos(P) = \\frac{77}{85}$. If the perimeter of triangle $PQR$ is $198$, what is the area of triangle $PQR$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1386', ARRAY['1386'], E'Since $\\cos(P) = \\frac{PQ}{PR} = \\frac{77}{85}$, the sides of the triangle are proportional to a right triangle with legs $36$ and $77$ and hypotenuse $85$ (since $\\sin(P) = \\frac{QR}{PR}$ and $36^2 + 77^2 = 1296 + 5929 = 7225 = 85^2$). Writing $PQ = 77k$, $QR = 36k$, and $PR = 85k$, the perimeter is $77k + 36k + 85k = 198k = 198$, so $k = 1$. The area is $\\frac{1}{2} \\times PQ \\times QR = \\frac{1}{2} \\times 77 \\times 36 = \\frac{2772}{2} = 1386$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23Z9AVZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of $200$ employees at a company found that $74$ commute by car, $53$ commute by train, and the rest commute by bus. Of those who commute by train, $19$ also work from home at least one day per week. If an employee who commutes by train is selected at random, what is the probability that this employee also works from home at least one day per week?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{19}{200}$"},{"key":"B","text":"$\\frac{19}{53}$"},{"key":"C","text":"$\\frac{53}{200}$"},{"key":"D","text":"$\\frac{19}{73}$"}]$lyceon_json$::jsonb, 'B', NULL, E'This is a conditional probability question. Given that the selected employee commutes by train, the sample space is restricted to the $53$ train commuters. Of these, $19$ also work from home at least one day per week, so the probability is $\\frac{19}{53}$. The distractor $\\frac{19}{200}$ incorrectly uses the total number of employees as the denominator instead of conditioning on train commuters. The distractor $\\frac{53}{200}$ gives the probability of being a train commuter overall, not the conditional probability. The distractor $\\frac{19}{73}$ uses the number of bus commuters ($200 - 74 - 53 = 73$) as the denominator, which is an arithmetic error in identifying the correct group.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM249GAOB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the age (in years) and resting heart rate (in beats per minute) of $30$ adults. The line of best fit is $y = -0.6x + 103$, where $x$ is age and $y$ is predicted resting heart rate. An adult who is $45$ years old has an actual resting heart rate of $82$ beats per minute. What is the residual for this data point?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$-6$"},{"key":"C","text":"$55$"},{"key":"D","text":"$-55$"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted value is $y = -0.6(45) + 103 = -27 + 103 = 76$. The residual is the actual value minus the predicted value: $82 - 76 = 6$. The value $-6$ reverses the subtraction order, computing predicted minus actual instead. The value $55$ comes from incorrectly computing the predicted value as $27$ (omitting the y-intercept addition) and then finding $82 - 27$. The value $-55$ compounds this prediction error with the reversed subtraction order.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24C17OG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A pharmaceutical company conducts a study to test a new headache medication. Volunteers are randomly assigned to receive either the medication or a placebo. Neither the volunteers nor the researchers administering the treatment know which group each volunteer is in. After $2$ weeks, the group receiving the medication reports a statistically significant reduction in headache frequency compared to the placebo group. A critic argues that the results may be biased because all volunteers were recruited from a single hospital in one city. Which of the following best addresses the critic''s concern?', NULL, $lyceon_json$[{"key":"A","text":"The concern is valid: because the sample is drawn from one location, a causal conclusion cannot be drawn from the study."},{"key":"B","text":"The concern is valid: the double-blind design eliminates treatment bias, but recruiting from a single hospital limits the generalizability of the results to a broader population."},{"key":"C","text":"The concern is not valid: random assignment ensures the results can be generalized to all headache sufferers."},{"key":"D","text":"The concern is not valid: the placebo group controls for any differences between the hospital's patients and the general population."}]$lyceon_json$::jsonb, 'B', NULL, E'The study uses random assignment and a double-blind design, which supports a causal conclusion within the studied sample: the medication likely caused the reduction in headache frequency compared to the placebo. However, the critic correctly notes that recruiting from a single hospital limits generalizability; the sample may not represent the broader population of headache sufferers. The distractor claiming no causal conclusion can be drawn is wrong because random assignment does support causation within the sample. The distractor claiming random assignment ensures generalizability confuses random assignment (which supports causation) with random sampling (which supports generalizability). The distractor about the placebo group controlling for population differences mischaracterizes the purpose of a placebo group; it controls for the placebo effect and participant expectations, not for sampling limitations.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24P2UK0', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A delivery service charges \\$11 per package for standard delivery and \\$19 per package for express delivery. A business ships $p$ packages via standard delivery and $q$ packages via express delivery. The business must ship at least $13$ packages total but cannot spend more than \\$209. Which system of inequalities represents these constraints?', NULL, $lyceon_json$[{"key":"A","text":"$p + q \\geq 13$ and $11p + 19q \\leq 209$"},{"key":"B","text":"$p + q \\leq 13$ and $11p + 19q \\leq 209$"},{"key":"C","text":"$p + q \\geq 13$ and $19p + 11q \\leq 209$"},{"key":"D","text":"$p + q > 13$ and $11p + 19q < 209$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of packages is $p + q$, which must be at least $13$, so $p + q \\geq 13$. The total cost is $11p + 19q$, which must not exceed $209$, so $11p + 19q \\leq 209$. Writing $p + q \\leq 13$ reverses the direction of the "at least" constraint. Swapping the coefficients to $19p + 11q$ assigns the express rate to standard packages and vice versa. Using strict inequalities ($>$ and $<$) misinterprets "at least" and "no more than," both of which include the boundary values.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24UKQDD', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A chemist has $250$ milliliters of a $42\\%$ saline solution. She adds pure water to dilute it to a $12\\%$ saline solution. What is the total volume, in milliliters, of the resulting $12\\%$ solution?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '875', ARRAY['875'], E'The amount of salt in the original solution is $0.42 \\times 250 = 105$ milliliters of salt. After adding pure water, the salt content stays at $105$ mL but the concentration becomes $12\\%$. Setting up the equation $\\frac{105}{V} = 0.12$ gives $V = \\frac{105}{0.12} = 875$ milliliters. A common error is computing only the amount of water added ($875 - 250 = 625$ mL) instead of the total volume. Another error is setting up the equation as $\\frac{0.12 \\times 250}{0.42}$, which confuses the original and final volumes and yields approximately $71.4$ mL.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24WND71', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples are taken from the same large population. Sample A consists of $250$ individuals and finds that $58\\%$ favor a policy change, with a margin of error of $\\pm 6.1\\%$. Sample B consists of $1{,}000$ individuals and finds that $51\\%$ favor the policy change, with a margin of error of $\\pm 3.1\\%$. Which of the following statements is most accurate?', NULL, $lyceon_json$[{"key":"A","text":"Sample A provides a more reliable estimate because its sample proportion is higher."},{"key":"B","text":"The two confidence intervals overlap, so the results are not necessarily inconsistent."},{"key":"C","text":"Sample B must be incorrect because its estimate differs from Sample A's estimate."},{"key":"D","text":"The margin of error for Sample A is larger because the population proportion is farther from $50\\%$."}]$lyceon_json$::jsonb, 'B', NULL, E'Sample A''s confidence interval is $(51.9\\%, 64.1\\%)$ and Sample B''s confidence interval is $(47.9\\%, 54.1\\%)$. These intervals overlap in the range $(51.9\\%, 54.1\\%)$, meaning the results are not necessarily inconsistent with each other; the true population parameter could plausibly lie in the overlap region. The distractor claiming Sample A is more reliable because its proportion is higher confuses the magnitude of a point estimate with reliability; Sample B actually has a smaller margin of error due to its larger sample size, making it more precise. The distractor claiming Sample B must be incorrect treats any difference between samples as contradictory, ignoring expected sampling variability. The distractor about margin of error being larger because the proportion is farther from $50\\%$ is factually wrong; the larger margin of error for Sample A is primarily due to the smaller sample size.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM259AEWJ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In right triangle $DEF$, the right angle is at $E$. If $DE = 12$ and $DF = 37$, what is $\\sin(D)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{12}{37}$"},{"key":"B","text":"$\\frac{35}{37}$"},{"key":"C","text":"$\\frac{12}{35}$"},{"key":"D","text":"$\\frac{37}{35}$"}]$lyceon_json$::jsonb, 'B', NULL, E'First, find $EF$ using the Pythagorean theorem: $EF = \\sqrt{DF^2 - DE^2} = \\sqrt{1369 - 144} = \\sqrt{1225} = 35$. Since $\\sin(D) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{EF}{DF} = \\frac{35}{37}$, this is the correct value. The ratio $\\frac{12}{37}$ is $\\cos(D)$, not $\\sin(D)$, confusing the adjacent side with the opposite side. The ratio $\\frac{12}{35}$ uses adjacent over opposite, which is neither a standard trig ratio of angle $D$ nor correctly structured. The ratio $\\frac{37}{35}$ inverts the sine ratio, placing the hypotenuse over the opposite side.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25FW1JA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A biologist models the relationship between the dosage $d$ (in milligrams) of a nutrient and the growth $g$ (in centimeters) of a plant over $4$ weeks using the equation $g = -0.03d^2 + 1.74d + 2.1$. According to this model, which of the following is closest to the dosage that maximizes the plant''s growth?', NULL, $lyceon_json$[{"key":"A","text":"$29$"},{"key":"B","text":"$58$"},{"key":"C","text":"$87$"},{"key":"D","text":"$27.3$"}]$lyceon_json$::jsonb, 'A', NULL, E'The growth function is a downward-opening parabola, so the maximum occurs at the vertex. The vertex of $g = -0.03d^2 + 1.74d + 2.1$ is at $d = \\frac{-1.74}{2(-0.03)} = \\frac{-1.74}{-0.06} = 29$. The value $58$ comes from using $\\frac{-b}{a}$ instead of $\\frac{-b}{2a}$, omitting the factor of $2$ in the denominator. The value $87$ arises from computing $\\frac{1.74}{0.02}$ due to a coefficient error in the denominator. The value $27.3$ results from an arithmetic slip in the final division.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25QRKWS', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'The system of equations below has two solutions. What is the sum of the $x$-coordinates of both solutions?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM263NLJL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set contains the values $3, 7, 7, 11, 11, 11, 14, 14, 19$. What is the mode of this data set?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$11$"},{"key":"C","text":"$14$"},{"key":"D","text":"$10.78$"}]$lyceon_json$::jsonb, 'B', NULL, E'The mode is the value that appears most frequently. The value $11$ appears $3$ times, which is more than any other value. The value $7$ appears only $2$ times, so it is the second most frequent but not the mode. The value $14$ also appears $2$ times and is not the most frequent. The value $10.78$ is approximately the mean of the data set ($\\frac{97}{9} \\approx 10.78$), not the mode.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26O5JFL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A factory produces bolts at a rate of $340$ bolts per hour using $4$ machines running simultaneously. Each machine operates at the same constant rate. If $3$ of the machines break down and only $1$ machine remains operational, how many minutes will it take the remaining machine to produce $255$ bolts?', NULL, $lyceon_json$[{"key":"A","text":"$180$"},{"key":"B","text":"$45$"},{"key":"C","text":"$120$"},{"key":"D","text":"$170$"}]$lyceon_json$::jsonb, 'A', NULL, E'Each machine produces $\\frac{340}{4} = 85$ bolts per hour. To produce $255$ bolts with one machine takes $\\frac{255}{85} = 3$ hours, which is $3 \\times 60 = 180$ minutes. The value $45$ results from dividing $255$ by $340$ and converting to minutes without accounting for the reduction to one machine. The value $120$ comes from an error in computing the per-machine rate. The value $170$ results from treating the answer in hours as though it were in minutes and applying incorrect unit conversions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2976BAC', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{18x^5 - 27x^3 + 9x^2}{9x^2}$ for all $x \\neq 0$?', NULL, $lyceon_json$[{"key":"A","text":"$2x^3 - 3x$"},{"key":"B","text":"$2x^3 + 3x + 1$"},{"key":"C","text":"$2x^3 - 3x + 1$"},{"key":"D","text":"$2x^7 - 3x^5 + x^4$"}]$lyceon_json$::jsonb, 'C', NULL, E'Divide each term of the numerator by $9x^2$: $\\frac{18x^5}{9x^2} = 2x^3$, $\\frac{-27x^3}{9x^2} = -3x$, and $\\frac{9x^2}{9x^2} = 1$. This gives $2x^3 - 3x + 1$. The expression $2x^3 - 3x$ drops the constant term from the third fraction. The expression $2x^3 + 3x + 1$ applies an incorrect sign to the middle term, losing the negative. The expression $2x^7 - 3x^5 + x^4$ results from adding exponents instead of subtracting them when dividing powers of $x$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BAVZY0', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'What is the value of $t$ in the equation $\\frac{3(t + 4)}{5} - 7 = 2$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'Multiplying both sides of the equation by $5$ gives $3(t + 4) - 35 = 10$. Adding $35$ to both sides: $3(t + 4) = 45$. Dividing both sides by $3$: $t + 4 = 15$. Subtracting $4$ from both sides: $t = 11$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BEMYQN', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the positive solution of $2x^2 - 9x - 5 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{1}{2}$"},{"key":"B","text":"$\\frac{1}{2}$"},{"key":"C","text":"$\\frac{9}{4}$"},{"key":"D","text":"$5$"}]$lyceon_json$::jsonb, 'D', NULL, E'Using the quadratic formula with $a = 2$, $b = -9$, $c = -5$: the discriminant is $(-9)^2 - 4(2)(-5) = 81 + 40 = 121$, so $x = \\frac{9 \\pm 11}{4}$. This gives $x = \\frac{20}{4} = 5$ or $x = \\frac{-2}{4} = -\\frac{1}{2}$. The positive solution is $5$. The value $-\\frac{1}{2}$ is the negative solution, not the positive one. The value $\\frac{1}{2}$ results from dropping the negative sign on the other root. The value $\\frac{9}{4}$ comes from computing only $\\frac{-b}{2a}$, the axis of symmetry, rather than the actual roots.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C0BXFH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains $7$ red marbles, $11$ blue marbles, and $5$ green marbles. If one marble is selected at random, what is the probability that it is blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{11}{23}$"},{"key":"B","text":"$\\frac{7}{23}$"},{"key":"C","text":"$\\frac{5}{23}$"},{"key":"D","text":"$\\frac{11}{12}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of marbles is $7 + 11 + 5 = 23$. The probability of selecting a blue marble is the number of blue marbles divided by the total: $\\frac{11}{23}$. The distractor $\\frac{7}{23}$ results from counting red marbles instead of blue. The distractor $\\frac{5}{23}$ results from counting green marbles instead of blue. The distractor $\\frac{11}{12}$ results from dividing blue marbles by the sum of the other colors rather than the total count.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D7M5TR', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'grid_in', E'Line $p$ has the equation $5x + 3y = 21$. Line $q$ is perpendicular to line $p$ and passes through the point $(4, -1)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-17/5', ARRAY['-17/5', '-3.4'], E'The slope of line $p$ is $-\\frac{5}{3}$ (rewriting as $y = -\\frac{5}{3}x + 7$). A line perpendicular to $p$ has slope $\\frac{3}{5}$. Using point-slope form with $(4, -1)$: $y - (-1) = \\frac{3}{5}(x - 4)$, which gives $y + 1 = \\frac{3}{5}x - \\frac{12}{5}$. So $y = \\frac{3}{5}x - \\frac{12}{5} - 1 = \\frac{3}{5}x - \\frac{17}{5}$. The $y$-intercept is $-\\frac{17}{5}$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DHREO0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $150$ registered voters in a city found that $63$ support a proposed parks initiative. The margin of error for this estimate is $\\pm 7\\%$. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Between $35\\%$ and $49\\%$ of all registered voters in the city support the initiative."},{"key":"B","text":"It is plausible that the true percentage of all registered voters in the city who support the initiative is between $35\\%$ and $49\\%$."},{"key":"C","text":"Exactly $42\\%$ of all registered voters in the city support the initiative."},{"key":"D","text":"If the survey were repeated, exactly $42\\%$ of respondents would support the initiative each time."}]$lyceon_json$::jsonb, 'B', NULL, E'The sample proportion is $\\frac{63}{150} = 42\\%$. With a margin of error of $\\pm 7\\%$, the plausible range for the true population proportion is $42\\% - 7\\% = 35\\%$ to $42\\% + 7\\% = 49\\%$. The correct interpretation is that it is plausible the true percentage falls in this interval. The distractor stating the percentage definitively is between $35\\%$ and $49\\%$ treats the confidence interval as a certainty rather than a plausible range. The distractor claiming exactly $42\\%$ ignores the margin of error entirely. The distractor about repeated surveys confuses the concept of sampling variability with the meaning of a confidence interval.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EYCMBQ', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A gym charges a \\$29 monthly membership fee plus \\$4 per class attended. A member wants to spend no more than \\$61 in a month. Which inequality represents the number of classes $c$ the member can attend, and what is the maximum number of classes?', NULL, $lyceon_json$[{"key":"A","text":"$29 + 4c \\leq 61$; at most $8$ classes"},{"key":"B","text":"$4c - 29 \\leq 61$; at most $22$ classes"},{"key":"C","text":"$29 + 4c \\leq 61$; at most $7$ classes"},{"key":"D","text":"$29 + 4c < 61$; at most $7$ classes"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is $29 + 4c$, which must be at most $61$, giving $29 + 4c \\leq 61$. Subtracting $29$ yields $4c \\leq 32$, so $c \\leq 8$. The maximum is $8$ classes. Setting the inequality up as $4c - 29 \\leq 61$ reverses the role of the membership fee and produces an incorrect maximum of $22$. Getting at most $7$ classes results from an arithmetic slip such as computing $\\frac{32}{4}$ incorrectly or rounding down unnecessarily. Using strict inequality ($<$) rather than $\\leq$ misapplies the condition "no more than," which includes equality.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G2T96A', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A researcher wants to determine whether a new fertilizer increases tomato plant yield. She randomly assigns $60$ tomato plants to two groups: one group receives the new fertilizer and the other receives no fertilizer. After $8$ weeks, she compares the average yield of the two groups. What type of study is this?', NULL, $lyceon_json$[{"key":"A","text":"An observational study"},{"key":"B","text":"A randomized experiment"},{"key":"C","text":"A survey"},{"key":"D","text":"A case study"}]$lyceon_json$::jsonb, 'B', NULL, E'The researcher randomly assigns plants to treatment and control groups and imposes a treatment (the fertilizer), which makes this a randomized experiment. An observational study would involve observing existing conditions without imposing a treatment. A survey collects self-reported data from respondents, which does not apply to plants receiving treatments. A case study is an in-depth analysis of a single subject or small group, not a controlled comparison of two groups.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
