INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H8Z8GF', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does the system of equations below have no solution?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ITW0JS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'In the $xy$-plane, a circle has its center at $(2, -5)$ and passes through the point $(11, 7)$. What is the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '15', ARRAY['15'], E'The radius equals the distance from the center $(2, -5)$ to the point $(11, 7)$ on the circle. Using the distance formula: $r = \\sqrt{(11 - 2)^2 + (7 - (-5))^2} = \\sqrt{9^2 + 12^2} = \\sqrt{81 + 144} = \\sqrt{225} = 15$. A common error is to forget to account for the sign of the $y$-coordinates, computing $\\sqrt{81 + 4} = \\sqrt{85}$ instead. Another error is to neglect the square root, giving $r = 225$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J7519O', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A recipe for a batch of granola requires $\\frac{7}{4}$ cups of oats for every $\\frac{3}{2}$ cups of honey. If a baker uses $7$ cups of oats, how many cups of honey does the baker need?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$\\frac{49}{6}$"},{"key":"C","text":"$\\frac{21}{4}$"},{"key":"D","text":"$\\frac{14}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The ratio of oats to honey is $\\frac{7}{4} : \\frac{3}{2}$, which simplifies to $\\frac{7}{4} \\div \\frac{3}{2} = \\frac{7}{6}$ cups of oats per cup of honey. With $7$ cups of oats, the honey needed is $7 \\div \\frac{7}{6} = 7 \\times \\frac{6}{7} = 6$ cups. The value $\\frac{49}{6}$ results from inverting the proportion and multiplying $7$ by $\\frac{7}{6}$ instead of dividing. The value $\\frac{21}{4}$ comes from multiplying $7$ by $\\frac{3}{4}$ instead of using the correct ratio. The value $\\frac{14}{3}$ arises from an arithmetic error when simplifying the proportion.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JP0YUP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'In the $xy$-plane, a circle is defined by the equation $(x - 4)^2 + (y + 7)^2 = 81$. What is the area of this circle?', NULL, $lyceon_json$[{"key":"A","text":"$9\\pi$"},{"key":"B","text":"$18\\pi$"},{"key":"C","text":"$81\\pi$"},{"key":"D","text":"$162\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The standard form $(x - h)^2 + (y - k)^2 = r^2$ shows that $r^2 = 81$, so $r = 9$. The area is $\\pi r^2 = \\pi(81) = 81\\pi$. The value $9\\pi$ comes from using $\\pi r$ instead of $\\pi r^2$, stopping at the radius without squaring. The value $18\\pi$ comes from computing the circumference $2\\pi r = 2\\pi(9) = 18\\pi$ instead of the area. The value $162\\pi$ comes from incorrectly computing $2\\pi r^2$ instead of $\\pi r^2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K26E2G', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'Tank A initially contains $340$ liters of water and drains at a constant rate. After $17$ minutes, Tank A contains $153$ liters. Tank B starts empty and fills at a constant rate of $7$ liters per minute. After how many minutes from the start will both tanks contain the same amount of water?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '170/9', ARRAY['170/9', '18.88', '18.89'], E'The drain rate for Tank A is $\\frac{340 - 153}{17} = \\frac{187}{17} = 11$ liters per minute. The amount of water in Tank A after $t$ minutes is $A(t) = 340 - 11t$. The amount in Tank B is $B(t) = 7t$. Setting them equal: $340 - 11t = 7t$, so $340 = 18t$, giving $t = \\frac{340}{18} = \\frac{170}{9}$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K6THG1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A laptop originally priced at \\$1,350 is on sale for $22\\%$ off. What is the sale price of the laptop?', NULL, $lyceon_json$[{"key":"A","text":"\\$297"},{"key":"B","text":"\\$1,053"},{"key":"C","text":"\\$1,328"},{"key":"D","text":"\\$1,072"}]$lyceon_json$::jsonb, 'B', NULL, E'The discount is $0.22 \\times 1350 = 297$ dollars. The sale price is $1350 - 297 = 1053$ dollars, which is \\$1,053. The value \\$297 represents only the discount amount, not the sale price. The value \\$1,328 results from subtracting $22$ dollars instead of $22\\%$ of the price. The value \\$1,072 comes from an arithmetic error when computing the product $0.22 \\times 1350$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KBGUQJ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'A surveyor standing $47$ meters from the base of a building measures the angle of elevation to the top of the building as $62°$. Which of the following expressions gives the height of the building, in meters?', NULL, $lyceon_json$[{"key":"A","text":"$47\\sin(62°)$"},{"key":"B","text":"$47\\cos(62°)$"},{"key":"C","text":"$47\\tan(62°)$"},{"key":"D","text":"$\\frac{47}{\\tan(62°)}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The situation forms a right triangle where the horizontal distance ($47$ m) is adjacent to the $62°$ angle and the building height is opposite it. Since $\\tan(62°) = \\frac{\\text{opposite}}{\\text{adjacent}} = \\frac{\\text{height}}{47}$, the height equals $47\\tan(62°)$. The expression $47\\sin(62°)$ incorrectly uses sine, which would require the hypotenuse to be $47$, not the adjacent side. The expression $47\\cos(62°)$ similarly misidentifies which side is $47$ meters. The expression $\\frac{47}{\\tan(62°)}$ inverts the tangent relationship, which would give the adjacent side if the opposite side were $47$, not the other way around.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LFLV0Y', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular garden has a length of $19$ feet and a width of $13$ feet. What is the area of the garden, in square feet?', NULL, $lyceon_json$[{"key":"A","text":"$32$"},{"key":"B","text":"$64$"},{"key":"C","text":"$247$"},{"key":"D","text":"$237$"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of a rectangle is length times width: $19 \\times 13 = 247$ square feet. The value $32$ is simply $19 + 13$, which gives half the perimeter rather than the area. The value $64$ is the full perimeter $2(19 + 13) = 64$, confusing perimeter with area. The value $237$ results from an arithmetic error in multiplying $19 \\times 13$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LP4XRZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the exterior angle at vertex $R$ measures $131°$. If $\\angle P = 54°$, what is the measure, in degrees, of $\\angle Q$?', NULL, $lyceon_json$[{"key":"A","text":"$49°$"},{"key":"B","text":"$77°$"},{"key":"C","text":"$87°$"},{"key":"D","text":"$103°$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the exterior angle theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles. So $131° = \\angle P + \\angle Q = 54° + \\angle Q$, giving $\\angle Q = 131° - 54° = 77°$. The value $49°$ comes from incorrectly computing $180° - 131°$, confusing the exterior angle''s supplement with a remote interior angle. The value $87°$ results from an arithmetic error in the subtraction. The value $103°$ comes from finding the interior angle at $R$ ($180° - 131° = 49°$) and then subtracting from $180°$ without including $\\angle P$, yielding $180° - 77° = 103°$, which is the wrong angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MWAAA5', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'What is the solution to $\\sqrt{5x + 19} = x + 1$?', NULL, $lyceon_json$[{"key":"A","text":"$x = -3$ only"},{"key":"B","text":"$x = 3$"},{"key":"C","text":"$x = 6$ only"},{"key":"D","text":"$x = -3$ and $x = 6$"}]$lyceon_json$::jsonb, 'C', NULL, E'Squaring both sides: $5x + 19 = (x + 1)^2 = x^2 + 2x + 1$. Rearranging: $x^2 - 3x - 18 = 0$, which factors as $(x - 6)(x + 3) = 0$, giving $x = 6$ or $x = -3$. Checking $x = 6$: $\\sqrt{5(6) + 19} = \\sqrt{49} = 7$ and $6 + 1 = 7$, which is valid. Checking $x = -3$: $\\sqrt{5(-3) + 19} = \\sqrt{4} = 2$ but $-3 + 1 = -2$, and $2 \\neq -2$, so $x = -3$ is extraneous. The only solution is $x = 6$. Selecting $x = -3$ alone reflects choosing the extraneous root. Selecting $x = 3$ is a sign error when factoring. Including both $x = -3$ and $x = 6$ fails to eliminate the extraneous solution.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MZGDCW', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(2, 11)$ and $(5, 23)$. Which of the following is the equation of this line?', NULL, $lyceon_json$[{"key":"A","text":"$y = 4x + 3$"},{"key":"B","text":"$y = 4x - 3$"},{"key":"C","text":"$y = 3x + 5$"},{"key":"D","text":"$y = \\frac{3}{4}x + 11$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $\\frac{23 - 11}{5 - 2} = \\frac{12}{3} = 4$. Using point $(2, 11)$: $11 = 4(2) + b$, so $b = 3$. The equation is $y = 4x + 3$. The equation $y = 4x - 3$ has the correct slope but an incorrect sign on the $y$-intercept, resulting from subtracting $b$ instead of solving for it properly. The equation $y = 3x + 5$ reverses the rise and run in the slope calculation, getting $\\frac{3}{12}$ inverted to $3$, then adjusting $b$ accordingly. The equation $y = \\frac{3}{4}x + 11$ uses the inverted slope $\\frac{3}{4}$ and incorrectly sets the $y$-intercept equal to the $y$-coordinate of the first point.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N4BSKF', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A bookstore sells hardcover books for \\$21 each and paperback books for \\$7 each. On a certain day, the store sold $26$ books and collected \\$336 in total revenue. How many hardcover books were sold?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$11$"},{"key":"C","text":"$13$"},{"key":"D","text":"$15$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $h$ represent hardcover books and $p$ represent paperback books. The system is $h + p = 26$ and $21h + 7p = 336$. Substituting $p = 26 - h$ into the cost equation gives $21h + 7(26 - h) = 336$, which simplifies to $21h + 182 - 7h = 336$, then $14h = 154$, so $h = 11$. We can verify: $21(11) + 7(15) = 231 + 105 = 336$. The value $15$ is the number of paperback books, which results from answering the wrong variable. The value $13$ comes from a misread such as solving for a rounded intermediate. The value $7$ results from an arithmetic slip, for instance dividing $154$ by $22$ instead of $14$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NKV6D1', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of $x$ satisfies the inequality $5x - 11 > 24$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$6$"},{"key":"C","text":"$7$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'D', NULL, E'Adding $11$ to both sides gives $5x > 35$, and dividing both sides by $5$ gives $x > 7$. Only $9$ is strictly greater than $7$. The value $7$ is the boundary from solving $5x - 11 = 24$, but since the inequality is strict ($x > 7$), the value $7$ itself does not satisfy it. The value $6$ comes from an arithmetic slip such as dividing $20$ by $5$ and rounding. The value $5$ reflects a misunderstanding of the inequality direction or an error in the initial step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O06HFD', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two parallel lines are cut by a transversal. One of the angles formed measures $137°$. What is the measure, in degrees, of its alternate interior angle?', NULL, $lyceon_json$[{"key":"A","text":"$43°$"},{"key":"B","text":"$47°$"},{"key":"C","text":"$137°$"},{"key":"D","text":"$127°$"}]$lyceon_json$::jsonb, 'C', NULL, E'Alternate interior angles formed by two parallel lines and a transversal are congruent, so the alternate interior angle also measures $137°$. The value $43°$ results from computing the supplement $180° - 137°$, which would give a co-interior (same-side interior) angle rather than the alternate interior angle. The values $47°$ and $127°$ arise from arithmetic errors in the subtraction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O1ATVG', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'If $f(x) = 2x^3 - 5$, what is the value of $f(-3)$?', NULL, $lyceon_json$[{"key":"A","text":"$-49$"},{"key":"B","text":"$-59$"},{"key":"C","text":"$49$"},{"key":"D","text":"$-23$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = -3$: $f(-3) = 2(-3)^3 - 5 = 2(-27) - 5 = -54 - 5 = -59$. The value $-49$ results from incorrectly computing $-54 + 5$ instead of $-54 - 5$, a sign error on the constant. The value $49$ comes from treating $(-3)^3$ as positive $27$, yielding $2(27) - 5 = 49$. The value $-23$ results from computing $(-3)^3$ as $-9$ instead of $-27$, giving $2(-9) - 5 = -23$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OY900R', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $23$ centimeters. What is the circumference of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$11.5\\pi$ cm"},{"key":"B","text":"$23\\pi$ cm"},{"key":"C","text":"$46\\pi$ cm"},{"key":"D","text":"$132.25\\pi$ cm"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference of a circle is $C = \\pi d$, where $d$ is the diameter. Substituting $d = 23$ gives $C = 23\\pi$ cm. The value $11.5\\pi$ results from using $\\pi r$ (radius times $\\pi$) instead of $\\pi d$, effectively halving the correct answer. The value $46\\pi$ comes from applying $2\\pi d$ instead of $\\pi d$, doubling the diameter unnecessarily. The value $132.25\\pi$ results from computing $\\pi r^2 = \\pi(11.5)^2$, which is the area formula, not circumference.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PBNOHN', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In triangle $ABC$, $\\angle A = (3x + 7)°$, $\\angle B = (5x - 13)°$, and side $AB$ is extended through $B$ to point $D$, creating exterior angle $\\angle CBD = (7x + 1)°$. What is the measure, in degrees, of $\\angle C$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '58', ARRAY['58'], E'Since $\\angle B$ and $\\angle CBD$ form a linear pair, $\\angle B + \\angle CBD = 180°$. Substituting: $(5x - 13) + (7x + 1) = 180$, which simplifies to $12x - 12 = 180$, so $12x = 192$ and $x = 16$. Then $\\angle A = 3(16) + 7 = 55°$ and $\\angle B = 5(16) - 13 = 67°$. Since the angles of a triangle sum to $180°$, $\\angle C = 180° - 55° - 67° = 58°$. This can be verified using the exterior angle theorem: $\\angle CBD = \\angle A + \\angle C = 55° + 58° = 113°$, and $7(16) + 1 = 113°$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PCOT2X', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'The expression $\\frac{6x^3 + 14x^2 - 10x + 6}{2x + 6}$ can be written as $ax^2 + bx + c$, where $a$, $b$, and $c$ are constants. What is the value of $a + b + c$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2', ARRAY['2'], E'Factor $2$ from both the numerator and the denominator: $\\frac{2(3x^3 + 7x^2 - 5x + 3)}{2(x + 3)} = \\frac{3x^3 + 7x^2 - 5x + 3}{x + 3}$. Performing polynomial long division or synthetic division with $x = -3$: $3x^3 + 7x^2 - 5x + 3 = (x + 3)(3x^2 - 2x + 1)$. So the expression equals $3x^2 - 2x + 1$, giving $a = 3$, $b = -2$, $c = 1$. Therefore $a + b + c = 3 + (-2) + 1 = 2$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QDK5MG', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'A store charges a flat fee of $\\$13$ for delivery plus $\\$4$ per item. A second store charges no delivery fee but $\\$6$ per item. For how many items is the total cost the same at both stores?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{13}{10}$"},{"key":"B","text":"$\\frac{13}{2}$"},{"key":"C","text":"$13$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting the total costs equal: $13 + 4n = 6n$. Subtracting $4n$ from both sides gives $13 = 2n$, so $n = \\frac{13}{2}$. The value $\\frac{13}{10}$ results from incorrectly adding the per-item rates ($4 + 6 = 10$) instead of subtracting them. The value $13$ comes from failing to account for the difference in per-item pricing and treating the flat fee as the answer. The value $3$ comes from subtracting the per-item prices ($6 - 4 = 2$) and then rounding $\\frac{13}{2}$ down incorrectly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R0CLMI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'The population of a town was $12,400$ in 2018. By 2023, the population had increased to $14,508$. What is the approximate percent increase in the town''s population from 2018 to 2023?', NULL, $lyceon_json$[{"key":"A","text":"$14.5\\%$"},{"key":"B","text":"$17\\%$"},{"key":"C","text":"$2{,}108\\%$"},{"key":"D","text":"$85.4\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The increase is $14508 - 12400 = 2108$. The percent increase is $\\frac{2108}{12400} \\times 100 \\approx 17\\%$. The value $14.5\\%$ results from dividing the increase by the final population ($\\frac{2108}{14508}$) rather than the original population. The value $2{,}108\\%$ comes from reporting the raw difference as a percentage without dividing by the original population. The value $85.4\\%$ results from computing $\\frac{12400}{14508} \\approx 0.854$ and misinterpreting this ratio as the percent increase.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"unit_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RC44CM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'A teacher records the following test scores for $11$ students: $58, 63, 67, 71, 74, 74, 78, 82, 85, 89, 93$. The teacher discovers that the score of $58$ was recorded in error and should have been $73$. What is the positive difference between the median of the corrected data set and the median of the original data set?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '0', ARRAY['0'], E'In the original ordered data set ($58, 63, 67, 71, 74, 74, 78, 82, 85, 89, 93$), the median is the $6$th value, which is $74$. After correcting $58$ to $73$, the new ordered data set is $63, 67, 71, 73, 74, 74, 78, 82, 85, 89, 93$. The median is still the $6$th value, which is $74$. The positive difference is $74 - 74 = 0$. A common error is computing the change in the mean (which does change by $\\frac{15}{11}$) rather than the median. Another trap is assuming any change to a data value must change the median, but since the corrected value ($73$) remains below the median ($74$), the median is unaffected.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RFVL18', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows a strong positive linear association between the number of hours studied and the score on a quiz. The line of best fit is $y = 4.7x + 52$, where $x$ is the number of hours studied and $y$ is the predicted quiz score. What is the predicted quiz score for a student who studied for $6$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$80.2$"},{"key":"B","text":"$56.7$"},{"key":"C","text":"$28.2$"},{"key":"D","text":"$76.7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 6$ into the equation gives $y = 4.7(6) + 52 = 28.2 + 52 = 80.2$. The value $56.7$ results from adding $4.7$ to $52$ only once rather than multiplying by $6$. The value $28.2$ comes from computing only the product $4.7 \\times 6$ and forgetting to add the y-intercept of $52$. The value $76.7$ results from an arithmetic slip such as computing $4.7 \\times 6 = 24.7$ instead of $28.2$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RZ4XZN', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $3x(7x - 11) + 4$?', NULL, $lyceon_json$[{"key":"A","text":"$21x^2 - 33x + 4$"},{"key":"B","text":"$21x^2 - 11x + 4$"},{"key":"C","text":"$10x^2 - 33x + 4$"},{"key":"D","text":"$21x^2 - 33x + 12$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing $3x$ over $(7x - 11)$ gives $3x \\cdot 7x = 21x^2$ and $3x \\cdot (-11) = -33x$. Adding the constant $4$ yields $21x^2 - 33x + 4$. The expression $21x^2 - 11x + 4$ results from failing to multiply $-11$ by $3$ when distributing. The expression $10x^2 - 33x + 4$ comes from adding $3$ and $7$ instead of multiplying $3x \\cdot 7x$. The expression $21x^2 - 33x + 12$ incorrectly multiplies the constant $4$ by $3$ as though it were inside the parentheses.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UGR76R', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A class of $31$ students was surveyed about whether they study music, play a sport, or both. Of the $31$ students, $13$ study music, $17$ play a sport, and $4$ do neither. A student from this class is chosen at random. Given that the student studies music, what is the probability that the student also plays a sport?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{3}{31}$"},{"key":"B","text":"$\\frac{3}{17}$"},{"key":"C","text":"$\\frac{3}{13}$"},{"key":"D","text":"$\\frac{17}{31}$"}]$lyceon_json$::jsonb, 'C', NULL, E'First, find how many students do at least one activity: $31 - 4 = 27$. By the inclusion-exclusion principle, the number who do both is $13 + 17 - 27 = 3$. The conditional probability that a student plays a sport given that the student studies music is $\\frac{3}{13}$, since we restrict the sample space to the $13$ music students. The distractor $\\frac{3}{31}$ divides by the total class size instead of conditioning on music students. The distractor $\\frac{3}{17}$ conditions on sport players instead of music students. The distractor $\\frac{17}{31}$ gives the unconditional probability of playing a sport, ignoring the condition entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UQ80WK', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A cone has a height of $9$ and a slant height of $15$. A cylinder has the same radius and height as the cone. What is the positive difference between the volume of the cylinder and the volume of the cone?', NULL, $lyceon_json$[{"key":"A","text":"$432\\pi$"},{"key":"B","text":"$864\\pi$"},{"key":"C","text":"$1296\\pi$"},{"key":"D","text":"$1728\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'First, find the radius using the Pythagorean theorem with the height and slant height: $r = \\sqrt{15^2 - 9^2} = \\sqrt{225 - 81} = \\sqrt{144} = 12$. The volume of the cylinder is $\\pi r^2 h = \\pi(144)(9) = 1296\\pi$. The volume of the cone is $\\frac{1}{3}\\pi r^2 h = \\frac{1}{3}(1296\\pi) = 432\\pi$. The positive difference is $1296\\pi - 432\\pi = 864\\pi$. The value $432\\pi$ is only the cone''s volume, not the difference. The value $1296\\pi$ is only the cylinder''s volume, ignoring the subtraction entirely. The value $1728\\pi$ results from adding the two volumes ($1296\\pi + 432\\pi$) instead of subtracting.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2URGHP8', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f(x) = x^2 - 14x + 53$ can be rewritten in vertex form as $f(x) = (x - h)^2 + k$. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$53$"},{"key":"C","text":"$7$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'D', NULL, E'Completing the square: $x^2 - 14x + 53 = (x^2 - 14x + 49) + 4 = (x - 7)^2 + 4$. So $k = 4$. The value $-4$ results from reversing the subtraction as $49 - 53 = -4$ instead of $53 - 49 = 4$. The value $53$ comes from reading the original constant term without completing the square. The value $7$ is the value of $h$, not $k$, answering the wrong part of the vertex form.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VFIYF1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'A store raises the price of an item by $15\\%$. Later, the store offers a discount of $15\\%$ on the new price. If the final price after the discount is \\$195.075, what was the original price, in dollars, of the item?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '200', ARRAY['200'], E'Let the original price be $p$. After a $15\\%$ increase, the price becomes $1.15p$. After a $15\\%$ discount on this new price, the final price is $0.85 \\times 1.15p = 0.9775p$. Setting $0.9775p = 195.075$ gives $p = \\frac{195.075}{0.9775} = 200$. A common error is assuming the $15\\%$ increase and $15\\%$ decrease cancel out, yielding the original price equals $195.075$. Another error is applying the percentages additively, treating the net change as $0\\%$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WZ7R4X', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'If $8x - 23 = 41$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$8$"},{"key":"C","text":"$\\frac{11}{7}$"},{"key":"D","text":"$-7$"}]$lyceon_json$::jsonb, 'B', NULL, E'Adding $23$ to both sides gives $8x = 64$, and dividing both sides by $8$ gives $x = 8$. The value $5$ results from dividing $41$ by $7$ and rounding incorrectly, ignoring the subtraction of $23$. The value $\\frac{11}{7}$ results from dividing $41$ by $7$ without first adding $23$. The value $-7$ results from a sign error when dividing.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X3IAXQ', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = 11x - 37$. What is the value of $g(6)$?', NULL, $lyceon_json$[{"key":"A","text":"$29$"},{"key":"B","text":"$103$"},{"key":"C","text":"$-31$"},{"key":"D","text":"$66$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 6$: $g(6) = 11(6) - 37 = 66 - 37 = 29$. The value $103$ results from adding $37$ instead of subtracting it. The value $-31$ results from computing $6 - 37 = -31$ and ignoring the coefficient $11$. The value $66$ results from only computing $11 \\times 6$ without subtracting $37$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YF00YP', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A plumber charges a \\$65 service fee plus \\$42 per hour of labor. The total charge, in dollars, for $h$ hours of labor is modeled by the function $C(h) = 42h + 65$. What is the best interpretation of the number $42$ in this function?', NULL, $lyceon_json$[{"key":"A","text":"The total charge, in dollars, for each job"},{"key":"B","text":"The estimated increase in total charge, in dollars, for each additional hour of labor"},{"key":"C","text":"The initial charge, in dollars, before any labor is performed"},{"key":"D","text":"The maximum number of hours the plumber will work"}]$lyceon_json$::jsonb, 'B', NULL, E'In the function $C(h) = 42h + 65$, the coefficient $42$ is the rate of change, representing the increase in total charge for each additional hour of labor. The interpretation that $42$ is the total charge for each job ignores the service fee and the variable nature of the cost. The interpretation that $42$ is the initial charge confuses the slope with the $y$-intercept, which is $65$. The interpretation that $42$ is the maximum hours confuses a dollar rate with a time quantity.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZE3P00', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $11x - 3y = 33$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, -11)$"},{"key":"B","text":"$(0, 9)$"},{"key":"C","text":"$(0, 4)$"},{"key":"D","text":"$(0, 36)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting $x = 0$ gives $-3y = 33$, so $y = -11$. The $y$-intercept is $(0, -11)$. The answer $(0, 9)$ results from neglecting the negative sign when dividing by $-3$. The answer $(0, 4)$ confuses the coefficient of $y$ with the intercept value. The answer $(0, 36)$ uses the constant on the right side without dividing by the coefficient of $y$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZZ8V08', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher randomly selects $400$ adults from a large city and finds that $37\\%$ of them exercise at least $4$ times per week. The margin of error for this estimate at a $95\\%$ confidence level is $\\pm 4.7\\%$. Which of the following conclusions is best supported by the data?', NULL, $lyceon_json$[{"key":"A","text":"Between $32.3\\%$ and $41.7\\%$ of all adults in the city exercise at least $4$ times per week."},{"key":"B","text":"The researcher is $95\\%$ confident that between $32.3\\%$ and $41.7\\%$ of all adults in the city exercise at least $4$ times per week."},{"key":"C","text":"If the study were repeated, $95\\%$ of the samples would yield a proportion of exactly $37\\%$."},{"key":"D","text":"Exactly $37\\%$ of all adults in the city exercise at least $4$ times per week, with $4.7\\%$ error."}]$lyceon_json$::jsonb, 'B', NULL, E'The sample proportion is $37\\%$, and the margin of error at $95\\%$ confidence is $\\pm 4.7\\%$, giving a confidence interval of $(32.3\\%, 41.7\\%)$. The correct statement includes the confidence level: the researcher is $95\\%$ confident the true population proportion falls in that interval. The distractor stating the range without mentioning the confidence level omits crucial qualifying language, presenting the interval as a definitive fact rather than a probabilistic statement. The distractor about repeated samples yielding exactly $37\\%$ mischaracterizes what confidence level means. The distractor claiming exactly $37\\%$ with error treats the sample proportion as a known population parameter.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20X8MQH', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Entomologists studying firefly populations in the Appalachian highlands have found that the synchronous flashing behavior of Photinus carolinus — in which thousands of individuals pulse in unison — occurs only during a narrow eleven-day mating window each June. Outside this window, the same fireflies flash in the irregular, individual patterns typical of other Photinus species. Because the synchronous behavior coincides exclusively with mating season and is absent at all other times, the researchers suggest that synchronous flashing most likely functions as ________', $lyceon_json$[{"key":"A","text":"a species-specific mating signal that helps females identify conspecific males among multiple co-occurring firefly species."},{"key":"B","text":"a territorial defense mechanism that deters competing insect species from occupying the same habitat."},{"key":"C","text":"a predator-avoidance strategy that confuses nocturnal birds by producing an overwhelming visual stimulus."},{"key":"D","text":"a thermoregulatory behavior triggered by the specific ambient temperatures present during mid-June evenings."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that synchronous flashing occurs only during the mating window and is absent otherwise, so the behavior is tied specifically to reproduction. The choice identifying it as a species-specific mating signal logically follows from the exclusive association with the mating period. The choice about territorial defense introduces a function — deterring other species — that the passage provides no basis for. The choice about predator avoidance proposes a survival function unconnected to the mating-season exclusivity the passage emphasizes. The choice about thermoregulation cites temperature as a trigger rather than a reproductive function, and the passage links the behavior to mating timing, not ambient conditions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21O98BS', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text as a whole?', E'The fruit fly Drosophila melanogaster has been a cornerstone of genetics research since Thomas Hunt Morgan''s pioneering experiments in 1910. Its genome contains approximately 13,600 genes, roughly 60 percent of which have recognizable counterparts in humans. _This genetic overlap makes Drosophila an invaluable model for studying human diseases such as Parkinson''s and Alzheimer''s._ Researchers can manipulate specific fly genes and observe the resulting effects within days, given the species'' rapid two-week generation cycle.', $lyceon_json$[{"key":"A","text":"It explains why a particular organism is useful for a specific area of scientific investigation."},{"key":"B","text":"It provides a historical account of how a scientific discovery was initially made."},{"key":"C","text":"It contrasts the genetic makeup of two different species to highlight their differences."},{"key":"D","text":"It questions whether a commonly used research method is still scientifically valid."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence states that genetic overlap between flies and humans makes Drosophila valuable for studying human diseases. This directly explains why the organism is useful for disease research. The option about providing a historical account is incorrect because the underlined sentence discusses current scientific utility, not history—the historical context appears in an earlier sentence about Morgan''s 1910 experiments. The option about contrasting genetic makeup misreads the passage: the underlined sentence draws a connection based on similarity (genetic overlap), not a contrast highlighting differences. The option about questioning a research method''s validity is incorrect because the passage consistently affirms Drosophila''s value as a model organism; no skepticism or challenge is expressed.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23JFND3', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1847, the physician Ignaz Semmelweis observed that mortality rates in maternity wards dropped dramatically when doctors washed their hands before examining _______ his contemporaries largely dismissed his findings, handwashing is now recognized as one of the most effective measures in infection control.', $lyceon_json$[{"key":"A","text":"patients. Although"},{"key":"B","text":"patients, although"},{"key":"C","text":"patients although"},{"key":"D","text":"patients: although"}]$lyceon_json$::jsonb, 'A', NULL, E'The blank falls between two complete thoughts: the first describes Semmelweis''s observation about handwashing, and the second introduces a concessive clause beginning with "although." A period after "patients" correctly ends the first sentence, and "Although" begins a new sentence containing the concessive clause followed by the main clause. The option "patients, although" creates a comma splice, fusing two sentences with only a comma. The option "patients although" produces a run-on sentence with no punctuation between the independent structures. The option "patients: although" misuses a colon, which should introduce an explanation or list that follows directly from the preceding clause, not a concessive contrast.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23QA5AX', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief introduction to a presentation about traditional Okinawan pottery. The student wants to emphasize the longevity of the craft. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24K8FYV', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the geologists who first surveyed the volcanic caldera in 1987 nor the volcanologist who revisited the site in 2019 _______ any seismic activity strong enough to suggest an imminent eruption, a finding that has shaped evacuation policy for the surrounding villages.', $lyceon_json$[{"key":"A","text":"has detected"},{"key":"B","text":"have detected"},{"key":"C","text":"were detecting"},{"key":"D","text":"are detecting"}]$lyceon_json$::jsonb, 'A', NULL, E'In a "neither...nor" construction, the verb agrees with the subject nearest to the verb. The nearest subject is "the volcanologist who revisited the site in 2019," which is singular, so the singular verb "has detected" is required. The present perfect tense is appropriate because the finding continues to influence current evacuation policy, as indicated by "has shaped." The option "have detected" uses a plural verb, which would agree with "geologists" but not with the nearer singular subject "volcanologist." The option "were detecting" uses past progressive tense, which implies ongoing activity at a specific past moment rather than a cumulative finding over time. The option "are detecting" uses present progressive tense, which conflicts with the completed surveys described in 1987 and 2019 and misrepresents the nature of the finding.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25DEQZR', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'During the 1923 Great Kanto earthquake, fires ravaged Tokyo for days, destroying roughly 381,000 homes. Architect Antonin Raymond, who had been practicing in Japan for several years, saw an opportunity to ______ the city''s building codes by incorporating reinforced concrete designs that could better resist seismic forces.', $lyceon_json$[{"key":"A","text":"overhaul"},{"key":"B","text":"commemorate"},{"key":"C","text":"replicate"},{"key":"D","text":"postpone"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes an architect who, after witnessing earthquake devastation, wanted to change building codes by introducing reinforced concrete designs. The blank needs a word meaning to fundamentally revise or reform. "Overhaul" means to thoroughly examine and repair or revise, fitting the idea of transforming outdated codes. "Commemorate" means to honor the memory of something, which has nothing to do with changing building standards. "Replicate" means to copy or reproduce exactly, which contradicts the passage''s emphasis on introducing new designs rather than copying existing ones. "Postpone" means to delay to a later time, which is illogical because the passage presents Raymond as seizing an immediate opportunity, not deferring action.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
