INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2A2CGGB', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second sentence in the text?', E'Economist Elinor Ostrom challenged the prevailing assumption that communities sharing a common resource will inevitably deplete it—a prediction formalized in Garrett Hardin''s influential 1968 "tragedy of the commons" thesis. Through fieldwork spanning irrigation systems in Nepal, fisheries in Nova Scotia, and forest management in Japan, Ostrom documented hundreds of cases in which communities devised their own governance rules—monitoring usage, sanctioning overuse, and adapting regulations over generations—to sustain shared resources without either privatization or state intervention. Her work demonstrated that the binary choice between market allocation and government control omitted a third, empirically robust alternative.', $lyceon_json$[{"key":"A","text":"It provides the empirical evidence that undermines the theoretical framework introduced in the first sentence."},{"key":"B","text":"It concedes a limitation in Ostrom's methodology before presenting her broader conclusion."},{"key":"C","text":"It offers a historical overview of resource management practices to contextualize a later claim."},{"key":"D","text":"It summarizes Ostrom's policy recommendations for governments managing common resources."}]$lyceon_json$::jsonb, 'A', NULL, E'The first sentence introduces Hardin''s theoretical prediction that shared resources will inevitably be depleted. The second sentence then presents Ostrom''s fieldwork across multiple countries documenting communities that successfully managed shared resources—direct empirical evidence contradicting the theory from the first sentence. The option about conceding a methodological limitation is incorrect because the second sentence presents no criticism or qualification of Ostrom''s approach; it straightforwardly reports her findings. The option about providing a historical overview partially captures the sentence''s reference to various governance systems but mischaracterizes their function: they serve as counter-evidence to Hardin''s thesis, not as neutral historical context. The option about policy recommendations is incorrect because the second sentence describes what communities independently devised, not what Ostrom recommended governments should do—the passage distinguishes between community self-governance and state intervention.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CDXA1G', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'The conventional view of metallic glass — an amorphous alloy cooled too rapidly for crystallization — holds that its atoms are arranged in a disordered, essentially random packing. However, computational simulations by Tanaka and colleagues at the University of Tokyo have revealed that metallic glasses possess a hidden medium-range order: clusters of atoms adopt icosahedral geometries that tile space in a non-periodic but non-random fashion, analogous to a three-dimensional Penrose tiling. This medium-range order, undetectable by standard X-ray diffraction because it lacks long-range periodicity, accounts for the anomalously high elastic limits observed in bulk metallic glasses — properties that pure disorder cannot explain. Tanaka''s framework thus repositions metallic glasses on the order-disorder spectrum: they are neither crystalline nor truly amorphous, but occupy a structurally intermediate state.', $lyceon_json$[{"key":"A","text":"Metallic glasses contain a previously undetected intermediate level of atomic order that explains their unusual mechanical properties and challenges the assumption that they are fully disordered."},{"key":"B","text":"Standard X-ray diffraction techniques have recently been improved to detect icosahedral clustering in metallic glasses, resolving a longstanding experimental limitation."},{"key":"C","text":"The elastic limits of metallic glasses are lower than those of crystalline metals because amorphous packing cannot sustain directional stress."},{"key":"D","text":"Penrose tilings were originally developed to model atomic arrangements in metallic glasses before being applied to two-dimensional quasicrystals."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage argues that metallic glasses are not truly random but possess medium-range icosahedral order that explains their anomalously high elastic limits, placing them between crystalline and fully amorphous. The choice stating that metallic glasses contain a previously undetected intermediate order that explains unusual properties and challenges the disorder assumption captures all layers of this argument. The choice about X-ray diffraction improvements misreads the passage, which states the order is undetectable by standard diffraction, not that diffraction has been improved. The choice claiming elastic limits are lower than crystalline metals contradicts the passage''s description of anomalously high elastic limits. The choice about Penrose tilings being developed for metallic glasses reverses the analogy; the passage uses Penrose tilings as a comparison, not as historically derived from metallic glass research.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CEAUVE', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Neuroscientist Yael Bhatt has been investigating why certain patients with damage to the ventromedial prefrontal cortex (vmPFC) perform normally on standard moral-reasoning questionnaires yet make strikingly utilitarian choices in real-stakes economic games — for instance, readily sacrificing one participant''s earnings to maximize total group payout. Bhatt hypothesizes that the vmPFC is not the seat of moral judgment itself but rather integrates somatic markers — gut-level emotional signals — into decision processes. Without these signals, patients can articulate conventional moral principles when asked abstractly but ________', $lyceon_json$[{"key":"A","text":"fail to weight those principles against competing emotional cues when making concrete decisions under genuine personal stakes."},{"key":"B","text":"demonstrate enhanced emotional responses in social situations, suggesting the vmPFC normally suppresses rather than generates somatic signals."},{"key":"C","text":"lose the ability to understand moral language altogether, rendering their questionnaire responses unreliable indicators of their reasoning."},{"key":"D","text":"consistently choose the option that minimizes total group payout, reflecting an inability to perform basic cost-benefit calculations."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a dissociation: vmPFC patients articulate moral principles normally in abstract questionnaires but make utilitarian choices in real-stakes situations. Bhatt''s hypothesis is that the vmPFC integrates emotional signals into decisions. The logical completion is that without those signals, patients cannot weight moral principles against emotional cues in concrete decisions — explaining why abstract reasoning is preserved but real-stakes behavior diverges. The choice about enhanced emotional responses contradicts the hypothesis that vmPFC damage removes somatic signals from decision-making rather than amplifying them. The choice about losing the ability to understand moral language contradicts the passage''s explicit statement that patients perform normally on moral-reasoning questionnaires. The choice about minimizing total group payout contradicts the passage, which says patients maximize group payout through utilitarian choices.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CGQSNP', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Literary critic Maryse Condé argued that the Négritude movement, while instrumental in affirming Black identity in the francophone world, ultimately ______ the very stereotypes it sought to dismantle by romanticizing a monolithic "African essence" that overlooked the continent''s vast cultural heterogeneity.', $lyceon_json$[{"key":"A","text":"entrenched"},{"key":"B","text":"cataloged"},{"key":"C","text":"disclosed"},{"key":"D","text":"arbitrated"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents a paradox: a movement meant to dismantle stereotypes inadvertently reinforced them by promoting a simplistic, romanticized view. The blank requires a word meaning to deepen or solidify those stereotypes. "Entrenched" means to establish something so firmly that change is difficult, capturing how the movement paradoxically solidified the stereotypes it aimed to destroy. "Cataloged" means to systematically list or classify items, which does not convey reinforcement of stereotypes—merely recording them is a neutral act unrelated to the critique. "Disclosed" means to reveal or make known something previously hidden, but the passage is not about revealing stereotypes; it is about inadvertently strengthening them. "Arbitrated" means to mediate or settle a dispute, which has no logical connection to the relationship between the movement and stereotypes described in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CIC3H6', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice most logically completes the text?', E'Historian Mariana Beltrán-Ochoa argues that the construction of railway networks in nineteenth-century Argentina served primarily to extract agricultural wealth from the interior for export, rather than to integrate regional economies. The rail lines converged radially on the port of Buenos Aires, bypassing lateral connections between provincial cities. _________ some scholars have noted that the railways inadvertently stimulated local commerce in towns along the main trunk routes, even if that commercial activity remained subordinate to the export-oriented design of the system.', $lyceon_json$[{"key":"A","text":"That said,"},{"key":"B","text":"Moreover,"},{"key":"C","text":"In effect,"},{"key":"D","text":"Similarly,"}]$lyceon_json$::jsonb, 'A', NULL, E'The final sentence introduces a partial counterpoint: while the railways were designed for extraction, they did stimulate some local commerce. This concessive relationship is best captured by "That said," which acknowledges the preceding argument while introducing a qualifying observation. "Moreover," would add a reinforcing point, but the final sentence partially qualifies rather than strengthens the extraction thesis. "In effect," would signal a summary or restatement of consequences, yet the final sentence introduces new, partially contrary information. "Similarly," would indicate a parallel case, but the stimulation of local commerce is a departure from, not a parallel to, the extraction-focused design described earlier.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
