INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GJQJKW', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Svalbard Global Seed Vault, carved into a mountainside on a remote Norwegian archipelago, stores duplicate samples of seeds from gene banks _______ its mission is to safeguard the world''s crop diversity against natural disasters and conflicts.', $lyceon_json$[{"key":"A","text":"worldwide, and"},{"key":"B","text":"worldwide and,"},{"key":"C","text":"worldwide. And"},{"key":"D","text":"worldwide, and,"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence contains two independent clauses joined by the coordinating conjunction "and." Standard English requires a comma before a coordinating conjunction that joins two independent clauses. The option "worldwide, and" correctly places the comma before "and" to join the clauses. The option "worldwide and," misplaces the comma after the conjunction rather than before it. The option "worldwide. And" unnecessarily fragments the sentence by starting a new sentence with "And" after a period, creating an incomplete thought. The option "worldwide, and," introduces a spurious second comma after "and" that has no grammatical function.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HT8M3C', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice most logically completes the text?', E'During the 1970s, Brazilian architect Lina Bo Bardi repurposed a former barrel factory in Salvador into a community arts center, preserving the industrial framework while introducing vibrant open-air gathering spaces. Her approach challenged the prevailing modernist tendency to demolish aging structures in favor of sleek new construction. _________ contemporary architects such as Adjaye and Wang Shu have cited Bo Bardi''s factory conversion as a direct influence on their own adaptive reuse projects.', $lyceon_json$[{"key":"A","text":"Consequently,"},{"key":"B","text":"By contrast,"},{"key":"C","text":"For instance,"},{"key":"D","text":"Accordingly,"}]$lyceon_json$::jsonb, 'D', NULL, E'The final sentence describes how later architects have followed Bo Bardi''s lead, which is a natural outgrowth of her influential approach described in the preceding sentences. "Accordingly," signals that what follows is consistent with and flows logically from the established precedent. "Consequently," implies a direct cause-and-effect, but the passage describes influence over decades rather than a strict causal chain, making it less precise. "By contrast," would signal opposition, yet the later architects are following Bo Bardi''s example, not contradicting it. "For instance," would introduce an example of the previous claim, but the sentence is presenting a result of her influence rather than an instance of her own work.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I4RGZA', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Marine biologists studying the seafloor near hydrothermal vents have found that certain species of tube worms can ______ extreme temperatures that would be lethal to most other organisms, thriving in waters that exceed 80 degrees Celsius.', $lyceon_json$[{"key":"A","text":"withstand"},{"key":"B","text":"generate"},{"key":"C","text":"regulate"},{"key":"D","text":"diminish"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes tube worms thriving in waters with extreme temperatures that would kill most organisms. The blank requires a word meaning to survive or endure those conditions. "Withstand" means to endure or resist successfully, which fits the context of surviving lethal temperatures. "Generate" means to produce or create, which reverses the relationship—the worms are not creating the temperatures. "Regulate" means to control or adjust, but the passage does not suggest the worms control the temperature; they simply survive it. "Diminish" means to reduce or make smaller, which implies the worms lower the temperature, contradicting the passage''s statement that the waters exceed 80 degrees Celsius.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IQLZJF', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice most logically completes the text?', E'Entomologist Dr. Keiko Furukawa has documented that the larvae of the emerald moth (Geometra papilionaria) attach fragments of birch flowers to their bodies as camouflage. _________ Furukawa found that larvae reared without access to plant material were significantly more likely to be detected by predatory wasps in controlled trials.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"Specifically,"},{"key":"C","text":"In contrast,"},{"key":"D","text":"Nevertheless,"}]$lyceon_json$::jsonb, 'B', NULL, E'The second sentence provides a specific experimental finding that illustrates the general claim in the first sentence about camouflage behavior. "Specifically," correctly signals that the following detail elaborates on the preceding general statement. "In other words," would indicate a restatement of the same idea, but the second sentence adds new experimental data rather than rephrasing. "In contrast," would signal an opposing idea, yet the second sentence supports the first. "Nevertheless," would indicate a concession or contradiction, which does not match the supportive relationship between the sentences.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J57SIA', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a report on an unusual geological feature. The student wants to present a contrast between the formation''s appearance and its actual composition. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JABX55', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Researchers at the Atacama Large Millimeter Array in Chile have detected complex organic molecules in the protoplanetary disk surrounding a young _______ the discovery suggests that the chemical building blocks of life may be present long before planets fully form.', $lyceon_json$[{"key":"A","text":"star;"},{"key":"B","text":"star,"},{"key":"C","text":"star"},{"key":"D","text":"star, but that"}]$lyceon_json$::jsonb, 'A', NULL, E'The blank separates two independent clauses: one about detecting organic molecules and one about the implication of the discovery. A semicolon correctly joins two closely related independent clauses without a coordinating conjunction. The option "star," creates a comma splice, which is a boundary error in Standard English. The option "star" with no punctuation produces a run-on sentence. The option "star, but that" is incorrect because the coordinating conjunction "and" implies the two clauses are equal additions, but the second clause draws a conclusion from the first, making a simple additive conjunction a poor fit; moreover, the subject shift from "researchers" to "the discovery" makes the semicolon the appropriate boundary marker for two related but structurally distinct independent clauses.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KCILG2', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The ceramicist Lucie Rie, who fled Vienna in 1938 and eventually settled in _______ produced stoneware vessels that combined the austere geometries of Bauhaus design with the luminous glazes of East Asian pottery traditions.', $lyceon_json$[{"key":"A","text":"London,"},{"key":"B","text":"London"},{"key":"C","text":"London;"},{"key":"D","text":"London:"}]$lyceon_json$::jsonb, 'A', NULL, E'The phrase "who fled Vienna in 1938 and eventually settled in London" is a nonrestrictive relative clause that interrupts the main clause "The ceramicist Lucie Rie ... produced stoneware vessels." Because this clause is set off by a comma before "who," a matching comma must follow "London" to close the nonrestrictive element. The option without any punctuation fails to close the parenthetical clause, leaving the sentence boundary unmarked and the main clause unresolved. The semicolon option incorrectly treats what follows as a second independent clause, but "produced stoneware vessels" has no separate subject and depends on "The ceramicist Lucie Rie" as its subject. The colon option implies that what follows is an explanation or elaboration of "London," which makes no sense in context.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LJBTIE', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding from the study, if accurate, would most directly weaken the claim made in the text?', E'Agricultural economists have argued that the adoption of precision agriculture technologies — such as GPS-guided variable-rate fertilizer applicators — consistently reduces total nitrogen runoff from large-scale grain farms. They point to field trials in which farms using variable-rate application achieved the same crop yields as conventionally managed farms while applying 18% less nitrogen fertilizer overall. The economists contend that lower fertilizer input necessarily translates to proportionally lower nitrogen losses to waterways.', $lyceon_json$[{"key":"A","text":"Watershed monitoring downstream of farms using variable-rate application showed nitrogen runoff levels only 4% lower than those downstream of conventionally managed farms of comparable size."},{"key":"B","text":"Farms using GPS-guided applicators reported a 22% reduction in fuel costs due to more efficient tractor routing across their fields."},{"key":"C","text":"Conventional farms that voluntarily reduced fertilizer application by 18% experienced an average yield decline of 11% over three growing seasons."},{"key":"D","text":"Soil scientists have determined that variable-rate applicators distribute fertilizer more evenly across field zones than conventional broadcast spreaders."}]$lyceon_json$::jsonb, 'A', NULL, E'The economists claim that 18% less fertilizer input necessarily translates to proportionally lower nitrogen runoff. The watershed data showing only a 4% reduction in runoff despite the 18% fertilizer reduction directly challenges the proportional relationship the economists assert, weakening their claim. The finding about reduced fuel costs addresses an economic benefit unrelated to nitrogen runoff. The finding about yield declines on conventional farms with reduced fertilizer concerns a different scenario and does not address whether precision application actually reduces runoff. The finding about more even distribution describes a mechanism of variable-rate applicators without addressing the resulting runoff levels.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LNV0OF', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Every spring, the coastal town of Nørhaven hosts a festival celebrating traditional boat-building techniques. This year, the festival''s organizing committee _______ invited master shipwrights from seven different countries to demonstrate their craft.', $lyceon_json$[{"key":"A","text":"has"},{"key":"B","text":"have"},{"key":"C","text":"are"},{"key":"D","text":"having"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject of the sentence is "the festival''s organizing committee," which is a singular collective noun. The singular verb form "has" correctly agrees with this subject to form the present perfect "has invited." The option "have" is a plural verb form that does not agree with the singular subject "committee." The option "are" would create "are invited," shifting the meaning to passive voice and changing the tense inappropriately, since the sentence indicates the committee performed the inviting. The option "having" is a participle that would create a sentence fragment, as "the committee having invited" lacks a finite verb to complete the main clause.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
