INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MN1RT1', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although the architectural firm had envisioned a rooftop garden featuring drought-resistant succulents, the building''s structural engineers determined that the roof _______ the additional weight without reinforcement of the load-bearing walls below.', $lyceon_json$[{"key":"A","text":"could not support"},{"key":"B","text":"can not have supported"},{"key":"C","text":"will not be supporting"},{"key":"D","text":"does not support"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence is set in the past tense, as indicated by "had envisioned" and "determined." The engineers'' conclusion about the roof''s capacity is a past-tense finding about ability, requiring the modal "could not support" to maintain tense consistency and convey inability. The option "can not have supported" uses a present-tense modal with a perfect infinitive, illogically suggesting the roof has never in its history supported weight, which misrepresents the engineers'' forward-looking assessment. The option "will not be supporting" shifts to future progressive tense, which conflicts with the past-tense narrative frame. The option "does not support" uses simple present tense, breaking the past-tense sequence established by the rest of the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2N3D39I', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Seeking to catalog every bryophyte species in the cloud forest, the research team spent fourteen months collecting specimens from moss-covered branches and _______ each sample''s moisture content, elevation, and canopy exposure in a field database that now contains over eleven thousand entries.', $lyceon_json$[{"key":"A","text":"recording"},{"key":"B","text":"recorded"},{"key":"C","text":"having recorded"},{"key":"D","text":"to record"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence uses the structure "spent fourteen months collecting ... and ___," where the blank must be parallel with "collecting." The present participle "recording" maintains parallel structure with "collecting" in the compound object of "spent fourteen months." The option "recorded" is a past-tense finite verb that breaks the parallel gerund structure required after "spent [time]." The option "having recorded" is a perfect participle that implies the recording was completed before the spending of time, which contradicts the sentence''s meaning that both activities occurred simultaneously during the fourteen months. The option "to record" is an infinitive that disrupts the "spent [time] + gerund" construction, which does not accept infinitives as complements in Standard English.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OVNHNG', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Tromsø have documented an unusual adaptation in Arctic reindeer: their eyes change color with the seasons. During the prolonged summer daylight, the tapetum lucidum — a reflective layer behind the retina — appears golden, reflecting most incoming light. In winter darkness, however, this layer shifts to a deep blue, scattering light within the eye and increasing retinal sensitivity. This seasonal shift allows reindeer to detect ultraviolet wavelengths that would be invisible to most mammals, helping them spot lichen beneath snow and identify predators against a white landscape.', $lyceon_json$[{"key":"A","text":"Arctic reindeer undergo a seasonal eye-color change that enhances their visual capabilities in varying light conditions."},{"key":"B","text":"The tapetum lucidum is a reflective structure found exclusively in Arctic reindeer and is absent in other mammals."},{"key":"C","text":"Ultraviolet wavelength detection is the primary survival mechanism used by most Arctic mammals during winter."},{"key":"D","text":"Researchers at the University of Tromsø have focused their careers on studying the physiology of Arctic wildlife."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how reindeer eyes change color seasonally and explains that this adaptation improves their vision in different light conditions. The choice stating that Arctic reindeer undergo a seasonal eye-color change enhancing their visual capabilities accurately captures this central idea. The choice claiming the tapetum lucidum is exclusive to reindeer misreads the passage, which says reindeer detect wavelengths invisible to most mammals but does not claim the structure itself is unique. The choice about ultraviolet detection being the primary mechanism of most Arctic mammals extends the passage''s claims beyond what is stated. The choice about the researchers'' career focus is a peripheral detail unsupported by the text.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QI9FRP', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In 1927, the bacteriologist Gruia Ionescu observed that certain strains of Bacillus mycoides grown on nutrient agar formed colonies that spiraled consistently in one direction — either clockwise or counterclockwise — and that this chirality was heritable across generations. Despite the finding''s reproducibility, it was largely ignored for decades. Recent work by microbiologists at the Weizmann Institute has revived interest in Ionescu''s observation, demonstrating that colony chirality correlates with the helical handedness of individual bacterial flagella and that mutations reversing flagellar helix direction also reverse colony spiral direction. These results suggest that macroscopic colony architecture is not random but is instead a direct physical consequence of single-cell-level asymmetry.', $lyceon_json$[{"key":"A","text":"Modern research has confirmed that the spiral direction of bacterial colonies is physically determined by the structural asymmetry of individual bacterial cells."},{"key":"B","text":"Gruia Ionescu was the first scientist to study bacterial colonies, but his methods were too rudimentary to yield reliable conclusions."},{"key":"C","text":"The Weizmann Institute has disproved Ionescu's original hypothesis about colony chirality by showing that flagellar mutations eliminate spiral patterns entirely."},{"key":"D","text":"Bacterial colonies exhibit random growth patterns that cannot be predicted from the properties of individual cells."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage traces how a historical observation about heritable colony chirality has been explained by modern research linking macroscopic spiral direction to single-cell flagellar asymmetry. The choice stating that modern research confirmed colony spiral direction is physically determined by individual cell asymmetry captures this arc. The choice calling Ionescu the first to study bacterial colonies and dismissing his methods misrepresents the passage, which says his findings were reproducible but ignored. The choice claiming the Weizmann Institute disproved Ionescu contradicts the passage, which indicates the modern work revived and extended his observation. The choice asserting random, unpredictable growth directly contradicts the passage''s conclusion.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QILR5V', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Marine ecologists studying coral reefs off the coast of Sulawesi have hypothesized that the bioluminescent displays produced by certain species of flashlight fish (Anomalops katoptron) serve primarily as a mechanism for coordinating group foraging behavior rather than for attracting prey. The researchers noted that the fish blink their suborbital light organs in synchronized patterns when moving in schools but switch to irregular, individual blinking when isolated.', $lyceon_json$[{"key":"A","text":"Schools of flashlight fish that were experimentally prevented from producing bioluminescent signals showed a 73% reduction in foraging efficiency compared to control schools."},{"key":"B","text":"Isolated flashlight fish attracted significantly more zooplankton when their light organs were uncovered than when they were artificially blocked."},{"key":"C","text":"Flashlight fish populations are denser in waters with lower ambient light levels, such as deep reef walls and caves."},{"key":"D","text":"The suborbital light organs of flashlight fish contain the same luciferin compound found in many other bioluminescent marine organisms."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis is that bioluminescence serves to coordinate group foraging. The finding that schools prevented from signaling suffered a major drop in foraging efficiency directly links the synchronized signals to foraging success, supporting the hypothesis. The finding about isolated fish attracting more zooplankton with uncovered light organs would support the alternative prey-attraction hypothesis, not the group-coordination one. The finding about population density in low-light environments is tangentially related to bioluminescence but does not address whether the light coordinates foraging. The finding about shared luciferin chemistry describes biochemistry without bearing on the behavioral function of the displays.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UFOLM5', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice most logically completes the text?', E'Microbiologist Tariq Nassar''s research team observed that certain strains of soil bacteria in arid regions produce hygroscopic exopolysaccharides—sticky compounds that draw moisture from the atmosphere. These secretions create thin biofilms on sand grains, enabling the bacteria to survive prolonged droughts. Nassar hypothesized that seeding degraded farmland with these bacteria might improve soil moisture retention. _________ preliminary field trials in Jordan''s Wadi Araba valley showed a 23 percent increase in topsoil water content over fourteen months, though the effect diminished markedly in plots where ambient humidity fell below 19 percent.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"In keeping with this hypothesis,"},{"key":"C","text":"On the other hand,"},{"key":"D","text":"For this reason,"}]$lyceon_json$::jsonb, 'B', NULL, E'The final sentence presents field trial results that largely supported Nassar''s hypothesis about improving soil moisture, while noting a limitation. "In keeping with this hypothesis," correctly signals that the experimental findings aligned with the prediction. "Furthermore," would merely add information without capturing the specific relationship between the hypothesis and the supporting evidence. "On the other hand," would indicate a contrasting point, but the trial results primarily confirmed the hypothesis rather than contradicting it. "For this reason," would imply that the trials were a consequence of the hypothesis itself, but the logical connection is between the hypothesis''s prediction and the confirming data, not a causal chain from hypothesis to outcome.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2V6PFF1', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which quotation from a literary critic, if included in the text, would most effectively illustrate the claim about Keene''s analytical method?', E'In a 2019 monograph, literary scholar Damaris Keene proposed that the recurring motif of failed navigation in Joseph Conrad''s lesser-known novellas — characters who misread charts, ignore compass headings, or anchor in the wrong harbor — functions as a structural analogue to the interpretive failures Conrad attributes to his narrators. Keene''s approach is distinctive because she treats spatial errors in the plot not as metaphors for psychological states but as formal devices that mirror the narrative''s own unreliable epistemology. By mapping each navigational mistake onto a corresponding moment where the narrator misapprehends events, Keene constructs a parallel architecture linking the diegetic world to the discourse level of the text.', $lyceon_json$[{"key":"A","text":"\"Keene's innovation lies in refusing allegory: she reads Conrad's wrong turns not as symbols of inner turmoil but as structural joints where story and storytelling expose each other's blind spots.\""},{"key":"B","text":"\"Keene's monograph is the most comprehensive biographical study of Conrad's maritime career to date, drawing on previously untranslated Polish correspondence.\""},{"key":"C","text":"\"While Keene's reading of Conrad is imaginative, it ultimately reduces navigational imagery to a single psychological diagnosis of each narrator's anxiety.\""},{"key":"D","text":"\"Keene joins a long tradition of critics who interpret Conrad's sea voyages as allegories for the colonial enterprise, though she extends the analysis to overlooked texts.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes Keene''s method as treating spatial errors not as metaphors for psychology but as formal devices paralleling narrative unreliability. The quotation about Keene refusing allegory and reading wrong turns as structural joints where story and storytelling expose each other''s blind spots directly illustrates this formal-structural approach. The quotation describing a biographical study of Conrad''s maritime career addresses a completely different scholarly method unrelated to the formal analysis the passage describes. The quotation reducing navigational imagery to a psychological diagnosis contradicts the passage''s explicit point that Keene avoids psychological readings. The quotation placing Keene in a tradition of colonial-allegory interpretation mischaracterizes her method, which the passage defines as structural rather than allegorical.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W3ESYY', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing an essay about municipal composting programs. The student wants to acknowledge a common objection to such programs while emphasizing evidence that the objection may be overstated. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WQ6EOG', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'When the Hawaiian island chain formed through volcanic activity over a geological hotspot, each island emerged at a different time, creating a natural chronosequence—a series of ecosystems of varying ages on similar substrates. Ecologist Peter Vitousek recognized that this chronosequence offered a rare opportunity: by studying soils and vegetation across islands of different ages, he could track how nutrient cycles evolve over millions of years without the confounding variables that plague studies conducted across geographically disparate sites. His subsequent research on the 4.1-million-year-old soils of Kauai and the 300-year-old lava flows of Kilauea revealed that phosphorus availability, not nitrogen, becomes the primary limiting nutrient in ecosystems older than approximately one million years.', $lyceon_json$[{"key":"A","text":"It introduces a natural phenomenon, explains how a researcher leveraged that phenomenon for scientific study, and then presents a key finding from that research."},{"key":"B","text":"It describes a geological process, critiques the methodology of previous studies, and proposes an alternative hypothesis about nutrient cycles."},{"key":"C","text":"It presents two competing theories about island formation and evaluates the evidence supporting each one."},{"key":"D","text":"It summarizes the career of a scientist and argues that his contributions have been underappreciated by the field."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage moves through three stages: it introduces the Hawaiian chronosequence (a natural phenomenon), explains how Vitousek used it as a research tool (leveraging the phenomenon), and then reports his finding about phosphorus as the limiting nutrient in old ecosystems (a key finding). The option about critiquing previous studies is incorrect because the passage mentions confounding variables in other studies only to explain the advantage of the chronosequence approach, not to critique specific prior work or propose an alternative hypothesis. The option about two competing theories misreads the passage, which presents a single geological explanation of island formation rather than competing theories. The option about summarizing a career and arguing for underappreciation introduces claims about recognition and career scope that the passage never makes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YG9FDZ', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Historians of technology have long credited Eli Whitney with pioneering the concept of interchangeable parts in American manufacturing. However, recent archival research by Merritt Roe Smith has shown that when the U.S. War Department tested Whitney''s 1801 musket demonstration, inspectors found that the parts required extensive hand-fitting and were not, in fact, interchangeable. The mythology surrounding Whitney persisted because it served a useful national narrative about American ingenuity. Smith''s findings suggest that Whitney''s actual contribution to manufacturing was not the implementation of interchangeability but rather ________', $lyceon_json$[{"key":"A","text":"the promotion of the idea of interchangeability as a desirable manufacturing goal, which inspired later engineers to develop the techniques that actually achieved it."},{"key":"B","text":"the invention of the cotton gin, which was a far more consequential technological achievement than any advance in firearms manufacturing."},{"key":"C","text":"the establishment of the first labor union for factory workers in the northeastern United States during the early nineteenth century."},{"key":"D","text":"the perfection of hand-fitting techniques that made each musket uniquely crafted and therefore more reliable than mass-produced alternatives."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that Whitney did not actually achieve interchangeability but that the idea persisted as a useful narrative. The logical completion is that Whitney''s real contribution was promoting the concept itself, which then influenced later engineers — this follows directly from the distinction between the mythology and the reality. The choice about the cotton gin introduces an entirely different invention outside the passage''s scope. The choice about founding a labor union has no support anywhere in the passage. The choice about perfecting hand-fitting contradicts the passage''s framing, which presents hand-fitting as evidence of Whitney''s failure to achieve interchangeability, not as a deliberate technique he perfected.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
